const moveBillingCycle = `-- name: MoveBillingCycle :exec
UPDATE billing_cycles SET subscription_cycle_id = $1, period_start = $2,
    period_end = $3, updated_at = now()
WHERE id = $4 AND status IN ('pending', 'due', 'failed')
`

type MoveBillingCycleParams struct {
	SubscriptionCycleID string
	PeriodStart         time.Time
	PeriodEnd           time.Time
	ID                  string
}

// Before an initial payment completes, its week can move (the cutoff of the
// planned first week passed while the customer was paying).
func (q *Queries) MoveBillingCycle(ctx context.Context, arg MoveBillingCycleParams) error {
	_, err := q.db.Exec(ctx, moveBillingCycle,
		arg.SubscriptionCycleID,
		arg.PeriodStart,
		arg.PeriodEnd,
		arg.ID,
	)
	return err
}

const nextInvoiceNumber = `-- name: NextInvoiceNumber :one

INSERT INTO invoice_counters (year, last) VALUES ($1, 1)
ON CONFLICT (year) DO UPDATE SET last = invoice_counters.last + 1
RETURNING last
`

// ---------------------------------------------------------------- invoices
func (q *Queries) NextInvoiceNumber(ctx context.Context, year int32) (int64, error) {
	row := q.db.QueryRow(ctx, nextInvoiceNumber, year)
	var last int64
	err := row.Scan(&last)
	return last, err
}

