const takeRedemption = `-- name: TakeRedemption :one
UPDATE promotions SET redemptions = redemptions + 1, updated_at = now()
WHERE id = $1 AND status = 'active' AND (max_redemptions IS NULL OR redemptions < max_redemptions)
RETURNING redemptions
`

// Counts a use, unless the promotion has run out. Concurrent checkouts are
// serialised by the row lock the UPDATE takes.
func (q *Queries) TakeRedemption(ctx context.Context, id string) (int32, error) {
	row := q.db.QueryRow(ctx, takeRedemption, id)
	var redemptions int32
	err := row.Scan(&redemptions)
	return redemptions, err
}

const useRedemptionCycle = `-- name: UseRedemptionCycle :exec
UPDATE promotion_redemptions SET cycles_used = least(cycles_used + 1, cycles_total), status = 'redeemed', updated_at = now()
WHERE subscription_id = $1 AND status <> 'released'
`

func (q *Queries) UseRedemptionCycle(ctx context.Context, subscriptionID string) error {
	_, err := q.db.Exec(ctx, useRedemptionCycle, subscriptionID)
	return err
}
